hatchet-engine.Text:
package main

import (
	"fmt"
	"log"
	"os"

	"github.com/spf13/cobra"

	"context"

	"github.com/hatchet-dev/hatchet/cmd/hatchet-engine/engine"
	"github.com/hatchet-dev/hatchet/pkg/cmdutils"
	"github.com/hatchet-dev/hatchet/pkg/config/loader"
)

var printVersion bool
var configDirectory string
var noGracefulShutdown bool

// rootCmd represents the base command when called without any subcommands
var rootCmd = &cobra.Command{
	Use:   "hatchet-engine",
	Short: "hatchet-engine runs the Hatchet engine.",
	Run: func(cmd *cobra.Command, args []string) {
		if printVersion {
			fmt.Println(Version)

			os.Exit(0)
		}

		cf := loader.NewConfigLoader(configDirectory)

		context := context.Background()
		if !noGracefulShutdown {
			ctx, cancel := cmdutils.NewInterruptContext()
			defer cancel()
			context = ctx
		}

		if err := engine.Run(context, cf, Version); err != nil {
			log.Printf("engine failure: %s", err.Error())
			os.Exit(1)
		}
	},
}

// Version will be linked by an ldflag during build
var Version = engine.DefaultVersion

func main() {
	rootCmd.PersistentFlags().BoolVar(
		&printVersion,
		"version",
		false,
		"print version and exit.",
	)

	rootCmd.PersistentFlags().StringVar(
		&configDirectory,
		"config",
		"",
		"The path the config folder.",
	)

	rootCmd.PersistentFlags().BoolVar(
		&noGracefulShutdown,
		"no-graceful-shutdown",
		false,
		"Whether not to shut down gracefully (useful for nodemon/air).",
	)

	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

hatchet-migrate.Text:
package main

import (
	"fmt"
	"os"
	"strconv"

	"github.com/spf13/cobra"

	"github.com/hatchet-dev/hatchet/cmd/hatchet-migrate/migrate"
	"github.com/hatchet-dev/hatchet/pkg/cmdutils"
	"github.com/hatchet-dev/hatchet/pkg/config/shared"
	"github.com/hatchet-dev/hatchet/pkg/logger"
)

var printVersion bool
var migrateDown string
var upToPenultimate bool
var upToVersion string

// rootCmd represents the base command when called without any subcommands
var rootCmd = &cobra.Command{
	Use:   "hatchet-migrate",
	Short: "hatchet-migrate runs database migrations for Hatchet.",
	Run: func(cmd *cobra.Command, args []string) {
		if printVersion {
			fmt.Println(Version)

			os.Exit(0)
		}

		ctx, cancel := cmdutils.NewInterruptContext()
		defer cancel()

		// the standalone command prints every migration diagnostic, so it runs
		// at debug level with the human-readable console writer
		l := logger.NewStdErr(&shared.LoggerConfigFile{Level: "debug", Format: "console"}, "migrate")

		if migrateDown != "" {
			migrate.RunDownMigration(ctx, migrateDown, migrate.WithLogger(&l))
		} else {
			if upToPenultimate && upToVersion != "" {
				fmt.Println("cannot use --up-to-penultimate and --up-to together")
				os.Exit(1)
			}

			opts := []migrate.RunMigrationsOpt{migrate.WithLogger(&l)}
			if upToPenultimate {
				opts = append(opts, migrate.WithUpToPenultimate())
			}
			if upToVersion != "" {
				version, err := strconv.ParseInt(upToVersion, 10, 64)
				if err != nil {
					fmt.Printf("invalid --up-to version %q: %v\n", upToVersion, err)
					os.Exit(1)
				}
				opts = append(opts, migrate.WithUpToVersion(version))
			}
			if err := migrate.RunMigrations(ctx, opts...); err != nil {
				fmt.Println(err)
				os.Exit(1)
			}
		}
	},
}

// Version will be linked by an ldflag during build
var Version = "v0.1.0-alpha.0"

func main() {
	rootCmd.PersistentFlags().BoolVar(
		&printVersion,
		"version",
		false,
		"print version and exit.",
	)

	rootCmd.PersistentFlags().StringVar(
		&migrateDown,
		"down",
		"",
		"migrate down to a specific version (e.g., 20240115180414).",
	)

	rootCmd.PersistentFlags().BoolVar(
		&upToPenultimate,
		"up-to-penultimate",
		false,
		"migrate up to the second-to-last migration version.",
	)

	rootCmd.PersistentFlags().StringVar(
		&upToVersion,
		"up-to",
		"",
		"migrate up to a specific goose version (e.g., 20260818184000).",
	)

	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

workflows.proto.Text:
syntax = "proto3";

option go_package = "github.com/hatchet-dev/hatchet/internal/services/shared/proto/v1";

package v1;

import "google/protobuf/timestamp.proto";
import "v1/shared/condition.proto";
import "v1/shared/trigger.proto";

// AdminService represents a set of RPCs for admin management of tasks, workflows, etc.
service AdminService {
    rpc PutWorkflow(CreateWorkflowVersionRequest) returns (CreateWorkflowVersionResponse);
    rpc CancelTasks(CancelTasksRequest) returns (CancelTasksResponse);
    rpc ReplayTasks(ReplayTasksRequest) returns (ReplayTasksResponse);
    rpc TriggerWorkflowRun(TriggerWorkflowRunRequest) returns (TriggerWorkflowRunResponse);
    rpc GetRunDetails(GetRunDetailsRequest) returns (GetRunDetailsResponse);
    rpc BranchDurableTask(BranchDurableTaskRequest) returns (BranchDurableTaskResponse);
}

message CancelTasksRequest {
    repeated string external_ids = 1; // a list of external UUIDs
    optional TasksFilter filter = 2;
}

message ReplayTasksRequest {
    repeated string external_ids = 1; // a list of external UUIDs
    optional TasksFilter filter = 2;
}

message TasksFilter {
    repeated string statuses = 1;
    google.protobuf.Timestamp since = 2;
    optional google.protobuf.Timestamp until = 3;
    repeated string workflow_ids = 4;
    repeated string additional_metadata = 5;
}

message CancelTasksResponse {
    repeated string cancelled_tasks = 1;
}

message ReplayTasksResponse {
    repeated string replayed_tasks = 1;
}

message TriggerWorkflowRunRequest {
    string workflow_name = 1;
    bytes input = 2;
    bytes additional_metadata = 3;
    optional int32 priority = 4;
    map<string, DesiredWorkerLabels> desired_worker_labels = 5;
}

message TriggerWorkflowRunResponse {
    string external_id = 1;
}

message BranchDurableTaskRequest {
    string task_external_id = 1; // (required) the external id (uuid) of the durable task
    int64 node_id = 2; // (required) the node id to branch from
    int64 branch_id = 3; // (required) the branch id to branch from
}

message BranchDurableTaskResponse {
    string task_external_id = 1; // the external id of the durable task
    int64 node_id = 2; // the node id of the new entry
    int64 branch_id = 3; // the branch id of the new entry
}

enum StickyStrategy {
    SOFT = 0;
    HARD = 1;
}

enum RateLimitDuration {
    SECOND = 0;
    MINUTE = 1;
    HOUR = 2;
    DAY = 3;
    WEEK = 4;
    MONTH = 5;
    YEAR = 6;
}

enum RunStatus {
    QUEUED = 0;
    RUNNING = 1;
    COMPLETED = 2;
    FAILED = 3;
    CANCELLED = 4;
    EVICTED = 5;
}


// CreateWorkflowVersionRequest represents options to create a workflow version.
message CreateWorkflowVersionRequest {
    string name = 1; // (required) the workflow name
    string description = 2; // (optional) the workflow description
    string version = 3; // (optional) the workflow version
    repeated string event_triggers = 4; // (optional) event triggers for the workflow
    repeated string cron_triggers = 5; // (optional) cron triggers for the workflow
    repeated CreateTaskOpts tasks = 6; // (required) the workflow jobs

    // Deprecated: use concurrency_arr instead
    Concurrency concurrency = 7; // (optional) the workflow concurrency options
    optional string cron_input = 8; // (optional) the input for the cron trigger
    optional CreateTaskOpts on_failure_task = 9; // (optional) the job to run on failure
    optional StickyStrategy sticky = 10; // (optional) the sticky strategy for assigning tasks to workers
    optional int32 default_priority = 11; // (optional) the default priority for the workflow
    repeated Concurrency concurrency_arr = 12; // (optional) the workflow concurrency options
    repeated DefaultFilter default_filters = 13; // (optional) the default filters for the workflow
    optional bytes input_json_schema = 14; // (optional) the JSON schema for the workflow input

    optional IdempotencyConfig idempotency = 15; // (optional) idempotency configuration for the workflow
}

enum IdempotencyMethod {
    TTL = 0;
    STATUS = 1;
}

message IdempotencyConfig {
    string expression = 1; // a CEL expression for determining the idempotency key for workflow runs
    int64 ttl_ms = 2; // time-to-live for idempotency keys in milliseconds. if the method is `STATUS`, this is a "fallback" - the longest the key can live before it's evicted
    optional IdempotencyMethod method = 3; // the method to use for idempotency, defaults to TTL
}

message IdempotencyCollisionError {
    string existing_run_external_id = 1; // the external ID of the existing workflow run that caused the collision
    string colliding_run_external_id = 2; // the external ID of the workflow run that caused the collision
}

message BulkTriggerIdempotencyCollisionError {
    repeated string successful_workflow_run_external_ids = 1; // the external IDs of the successfully triggered workflow runs
    repeated IdempotencyCollisionError collisions = 2; // the idempotency collision errors
}

message DefaultFilter {
    string expression = 1; // (required) the CEL expression for the filter
    string scope = 2; // (required) the scope of the filter
    optional bytes payload = 3; // (optional) the payload for the filter, if any. A JSON object as a string.
}

enum ConcurrencyLimitStrategy {
    CANCEL_IN_PROGRESS = 0;
    DROP_NEWEST = 1; // deprecated
    QUEUE_NEWEST = 2; // deprecated
    GROUP_ROUND_ROBIN = 3;
    CANCEL_NEWEST = 4;
    CANCEL_QUEUED_EXCEPT_NEWEST = 5;
    CANCEL_QUEUED_EXCEPT_OLDEST = 6;
}

// Concurrency declares one entry in a concurrency chain. Entries are processed in array
// order, so a tenant-scoped entry may come before or after a workflow-scoped one.
//
// A tenant-scoped entry (is_tenant_scoped = true) defines (or updates in place) a strategy
// shared across workflows, keyed by name: every task declaring the same name consumes the
// same concurrency limit. Registrations whose chains order the same tenant-scoped
// strategies inconsistently are rejected, since inconsistent orders can deadlock.
message Concurrency {
    string expression = 1; // (required) the expression to use for concurrency
    optional int32 max_runs = 2; // (optional) the maximum number of concurrent workflow runs, default 1
    optional ConcurrencyLimitStrategy limit_strategy = 3; // (optional) the strategy to use when the concurrency limit is reached, default CANCEL_IN_PROGRESS
    optional string name = 4; // (required when is_tenant_scoped) the strategy name; unique per tenant for tenant-scoped strategies
    optional bool is_tenant_scoped = 5; // (optional) when true, the entry is a tenant-scoped strategy shared across workflows, default false
    optional string max_runs_expression = 6; // (optional) CEL expression over task input returning the max runs for that task's concurrency group; the group's effective limit is the value from its most recently created task. Overrides max_runs per group; a non-integer or negative result fails the task, and 0 holds the group until a newer task raises the limit
}


message TaskBatchConfig {
    int32 batch_max_size = 1; // (required) maximum items per batch
    optional int32 batch_max_interval_ms = 2; // (optional) time before batch flushes (milliseconds)
    optional string batch_group_key = 3; // (optional) partition key for fairness (prevents mixing tenants)
    optional int32 batch_group_max_runs = 4; // (optional) concurrent batches per group
    optional bool broadcast_output = 5; // (optional) when true, the handler returns one value broadcast to all callers; when false (default), the handler returns a dict keyed by step run id
}

// CreateTaskOpts represents options to create a task.
message CreateTaskOpts {
    string readable_id = 1; // (required) the task name
    string action = 2; // (required) the task action id
    string timeout = 3; // (optional) the task timeout
    string inputs = 4; // (optional) the task inputs, assuming string representation of JSON
    repeated string parents = 5; // (optional) the task parents. if none are passed in, this is a root task
    int32 retries = 6; // (optional) the number of retries for the task, default 0
    repeated CreateTaskRateLimit rate_limits = 7; // (optional) the rate limits for the task
    map<string, DesiredWorkerLabels> worker_labels = 8; // (optional) the desired worker affinity state for the task
    optional float backoff_factor = 9; // (optional) the retry backoff factor for the task
    optional int32 backoff_max_seconds = 10; // (optional) the maximum backoff time for the task
    repeated Concurrency concurrency = 11; // (optional) the task concurrency options
    optional TaskConditions conditions = 12; // (optional) the task conditions for creating the task
    optional string schedule_timeout = 13; // (optional) the timeout for the schedule
    bool is_durable = 14; // (optional) whether the task is durable
    map<string, int32> slot_requests = 15; // (optional) slot requests (slot_type -> units)
    optional TaskBatchConfig batch = 16; // (optional) batch execution configuration
}

message CreateTaskRateLimit {
    string key = 1; // (required) the key for the rate limit
    optional int32 units = 2; // (optional) the number of units this task consumes
    optional string key_expr = 3; // (optional) a CEL expression for determining the rate limit key
    optional string units_expr = 4; // (optional) a CEL expression for determining the number of units consumed
    optional string limit_values_expr = 5; // (optional) a CEL expression for determining the total amount of rate limit units
    optional RateLimitDuration duration = 6; // (optional) the default rate limit window to use for dynamic rate limits
}

// CreateWorkflowVersionResponse represents the response after creating a workflow version.
message CreateWorkflowVersionResponse {
    string id = 1;
    string workflow_id = 2;
}

message GetRunDetailsRequest {
    string external_id = 1; // (required) the external id (uuid) of the workflow run
}

message TaskRunDetail {
    string external_id = 1; // the external id (uuid) of the task run
    RunStatus status = 2; // the status of the task run
    optional string error = 3; // (optional) error message from the task run, if any
    optional bytes output = 4; // (optional) the output payload for the task run
    string readable_id = 5; // the readable id of the task
    bool is_evicted = 6; // whether the task has been evicted from a worker (status will be RUNNING)
}

message GetRunDetailsResponse {
    bytes input = 1; // the input payload for the workflow run
    RunStatus status = 2; // the status of the workflow run
    map<string, TaskRunDetail> task_runs = 3; // map of task run external ids to their details
    bool done = 4; // indicates if the workflow run is done
    bytes additional_metadata = 5; // (optional) additional metadata for the workflow run
    bool is_evicted = 6; // whether any task in this run has been evicted
}

dispatcher.proto.Text:
syntax = "proto3";

option go_package = "github.com/hatchet-dev/hatchet/internal/services/shared/proto/v1";

package v1;

import "v1/shared/condition.proto";
import "v1/shared/trigger.proto";

service V1Dispatcher {
    rpc DurableTask(stream DurableTaskRequest) returns (stream DurableTaskResponse) {}

    // NOTE: deprecated after DurableEventLog is implemented
    rpc RegisterDurableEvent(RegisterDurableEventRequest) returns (RegisterDurableEventResponse) {}
    rpc ListenForDurableEvent(stream ListenForDurableEventRequest) returns (stream DurableEvent) {}
}

message DurableTaskRequestRegisterWorker {
    string worker_id = 1;
}

message DurableTaskResponseRegisterWorker {
    string worker_id = 1;
}

message DurableEventLogEntryRef {
    string durable_task_external_id = 1;
    int32 invocation_count = 2;
    int64 branch_id = 3;
    int64 node_id = 4;
}

message DurableTaskRunAckEntry {
    int64 node_id = 1;
    int64 branch_id = 2;
    string workflow_run_external_id = 3;
}

message DurableTaskEventMemoAckResponse {
    DurableEventLogEntryRef ref = 1;
    bool memo_already_existed = 2;
    optional bytes memo_result_payload = 3;
}

message DurableTaskEventTriggerRunsAckResponse {
    string durable_task_external_id = 1;
    int32 invocation_count = 2;
    repeated DurableTaskRunAckEntry run_entries = 3;
}

message DurableTaskEventWaitForAckResponse {
    DurableEventLogEntryRef ref = 1;
}

message DurableTaskEventLogEntryCompletedResponse {
    DurableEventLogEntryRef ref = 1;
    bytes payload = 2;
    bool is_failure = 3;
    optional string error_message = 4;
}

message DurableTaskEvictInvocationRequest {
    int32 invocation_count = 1;
    string durable_task_external_id = 2;
    optional string reason = 3;
}

// Sent by the server after recording eviction for an evict_invocation request.
message DurableTaskEvictionAckResponse {
    int32 invocation_count = 1;
    string durable_task_external_id = 2;
}

message DurableTaskAwaitedCompletedEntry {
    string durable_task_external_id = 1;
    int64 branch_id = 2;
    int64 node_id = 3;
    int32 invocation_count = 4;
}

// Sent by the server to notify a worker that its invocation is stale and should be cancelled.
message DurableTaskServerEvictNotice {
    string durable_task_external_id = 1;
    int32 invocation_count = 2;
    string reason = 3;
}

message DurableTaskWorkerStatusRequest {
    string worker_id = 1;
    repeated DurableTaskAwaitedCompletedEntry waiting_entries = 2;
}

message DurableTaskCompleteMemoRequest {
    DurableEventLogEntryRef ref = 1;
    bytes payload = 2;
    bytes memo_key = 3;
}

message DurableTaskMemoRequest {
    // The invocation_count is a monotonically increasing count that uniquely identifies an "attempt"
    // at running a durable task. Each time the task is started, it gets a new invocation count (which has)
    // incremented by one since the previous invocation. This allows the server (and the worker) to have a way of
    // differentiating between different attempts of the same task running in different places, to prevent race conditions
    // and other problems from duplication. It also allows for older invocations to be evicted cleanly
    int32 invocation_count = 1;
    string durable_task_external_id = 2;

    bytes key = 3;

    // optional payload because we can send a memo request to check if a memo already exists
    optional bytes payload = 4;
}

message DurableTaskTriggerRunsRequest {
    // The invocation_count is a monotonically increasing count that uniquely identifies an "attempt"
    // at running a durable task. Each time the task is started, it gets a new invocation count (which has)
    // incremented by one since the previous invocation. This allows the server (and the worker) to have a way of
    // differentiating between different attempts of the same task running in different places, to prevent race conditions
    // and other problems from duplication. It also allows for older invocations to be evicted cleanly
    int32 invocation_count = 1;
    string durable_task_external_id = 2;

    repeated TriggerWorkflowRequest trigger_opts = 3;
}

message DurableTaskWaitForRequest {
    // The invocation_count is a monotonically increasing count that uniquely identifies an "attempt"
    // at running a durable task. Each time the task is started, it gets a new invocation count (which has)
    // incremented by one since the previous invocation. This allows the server (and the worker) to have a way of
    // differentiating between different attempts of the same task running in different places, to prevent race conditions
    // and other problems from duplication. It also allows for older invocations to be evicted cleanly
    int32 invocation_count = 1;
    string durable_task_external_id = 2;

    // Fields for DURABLE_TASK_TRIGGER_KIND_WAIT_FOR
    optional DurableEventListenerConditions wait_for_conditions = 3;

    // An optional human-readable label for this wait, displayed in the dashboard.
    // Example: "Waiting for payment confirmation"
    optional string label = 4;
}

message DurableTaskRequest {
    oneof message {
        DurableTaskRequestRegisterWorker register_worker = 1;
        DurableTaskMemoRequest memo = 2;
        DurableTaskTriggerRunsRequest trigger_runs = 3;
        DurableTaskWaitForRequest wait_for = 4;
        DurableTaskEvictInvocationRequest evict_invocation = 5;
        DurableTaskWorkerStatusRequest worker_status = 6;
        DurableTaskCompleteMemoRequest complete_memo = 7;
    }
}

enum DurableTaskErrorType {
    DURABLE_TASK_ERROR_TYPE_UNSPECIFIED = 0;
    DURABLE_TASK_ERROR_TYPE_NONDETERMINISM = 1;
}

message DurableTaskErrorResponse {
    DurableEventLogEntryRef ref = 1;
    DurableTaskErrorType error_type = 2;
    string error_message = 3;
}

message DurableTaskResponse {
    oneof message {
        DurableTaskResponseRegisterWorker register_worker = 1;
        DurableTaskEventMemoAckResponse memo_ack = 2;
        DurableTaskEventTriggerRunsAckResponse trigger_runs_ack = 3;
        DurableTaskEventWaitForAckResponse wait_for_ack = 4;
        DurableTaskEventLogEntryCompletedResponse entry_completed = 5;
        DurableTaskErrorResponse error = 6;
        DurableTaskEvictionAckResponse eviction_ack = 7;
        DurableTaskServerEvictNotice server_evict = 8;
    }
}

message RegisterDurableEventRequest {
    string task_id = 1; // external uuid for the task run
    string signal_key = 2; // the signal key for the event
    DurableEventListenerConditions conditions = 3; // the task conditions for creating the task
}

message RegisterDurableEventResponse {
}

message ListenForDurableEventRequest {
    string task_id = 1; // single listener per worker
    string signal_key = 2; // the match id for the listener
}

message DurableEvent {
    string task_id = 1;
    string signal_key = 2;
    bytes data = 3; // the data for the event
}

trigger_handler.Text:
package workflowruns

import (
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/labstack/echo/v4"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/hatchet-dev/hatchet/api/v1/server/authz"
	"github.com/hatchet-dev/hatchet/api/v1/server/oas/apierrors"
	"github.com/hatchet-dev/hatchet/api/v1/server/oas/gen"
	contracts "github.com/hatchet-dev/hatchet/internal/services/shared/proto/v1"
	"github.com/hatchet-dev/hatchet/pkg/constants"
	v1 "github.com/hatchet-dev/hatchet/pkg/repository"
	"github.com/hatchet-dev/hatchet/pkg/repository/sqlcv1"
)

func (t *V1WorkflowRunsService) V1WorkflowRunCreate(ctx echo.Context, request gen.V1WorkflowRunCreateRequestObject) (gen.V1WorkflowRunCreateResponseObject, error) {
	tenant := ctx.Get("tenant").(*sqlcv1.Tenant)
	tenantId := tenant.ID

	// make sure input can be marshalled and unmarshalled to input type
	inputBytes, err := json.Marshal(request.Body.Input)

	if err != nil {
		return gen.V1WorkflowRunCreate400JSONResponse(
			apierrors.NewAPIErrors("Invalid input"),
		), nil
	}

	var additionalMetadataBytes []byte

	if request.Body.AdditionalMetadata != nil {

		additionalMetadataBytes, err = json.Marshal(request.Body.AdditionalMetadata)

		if err != nil {
			return gen.V1WorkflowRunCreate400JSONResponse(
				apierrors.NewAPIErrors("Invalid additional metadata"),
			), nil
		}
	}

	var priority *int32
	if request.Body.Priority != nil {
		if *request.Body.Priority < 1 || *request.Body.Priority > 3 {
			return gen.V1WorkflowRunCreate400JSONResponse(
				apierrors.NewAPIErrors(fmt.Sprintf("priority must be between 1 and 3, got %d", *request.Body.Priority)),
			), nil
		}

		newPrio := int32(*request.Body.Priority)
		priority = &newPrio
	}

	grpcReq := &contracts.TriggerWorkflowRunRequest{
		WorkflowName:       request.Body.WorkflowName,
		Input:              inputBytes,
		AdditionalMetadata: additionalMetadataBytes,
		Priority:           priority,
	}

	resp, err := t.proxyTrigger.Do(
		ctx.Request().Context(),
		tenant,
		grpcReq,
	)

	if err != nil {
		if e, ok := status.FromError(err); ok {
			switch e.Code() { // nolint: gocritic
			case codes.InvalidArgument:
				return gen.V1WorkflowRunCreate400JSONResponse(
					apierrors.NewAPIErrors(e.Message()),
				), nil
			case codes.ResourceExhausted:
				return gen.V1WorkflowRunCreate400JSONResponse(
					apierrors.NewAPIErrors(e.Message()),
				), nil
			}
		}

		return nil, err
	}

	if request.Body.ReturnOnlyId != nil && *request.Body.ReturnOnlyId {
		// this is a hack to avoid race conditions in replicating data over to the olap db. basically,
		// there's a situation where it takes longer than the polling time to replicate the run over (could happen
		// under load, e.g.), and then we'd 500 on this request even though the actual trigger happened successfully.
		// to avoid confusion, the frontend passes this boolean param, and we just short-circuit and return only the
		// id so we're not dependent on replication.
		return gen.V1WorkflowRunCreate200JSONResponse(
			gen.V1WorkflowRunDetails{
				Run: gen.V1WorkflowRun{
					Metadata: gen.APIResourceMeta{
						Id:        resp.ExternalId,
						CreatedAt: time.Now().UTC(),
						UpdatedAt: time.Now().UTC(),
					},
				},
			},
		), nil
	}

	// loop for workflow to be created in the OLAP database
	var rawWorkflowRun *v1.V1WorkflowRunPopulator
	retries := 0

	externalId, err := uuid.Parse(resp.ExternalId)

	if err != nil {
		return nil, fmt.Errorf("invalid external id returned from trigger workflow run: %w", err)
	}

	for retries < 10 {
		rawWorkflowRun, err = t.config.V1.OLAP().ReadWorkflowRun(
			ctx.Request().Context(),
			externalId,
		)

		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return nil, err
		}

		if err != nil && errors.Is(err, pgx.ErrNoRows) {
			retries++
			time.Sleep(1 * time.Second)
			continue
		}

		break
	}

	if rawWorkflowRun == nil || rawWorkflowRun.WorkflowRun == nil {
		return nil, fmt.Errorf("rawWorkflowRun not populated, we are likely seeing high latency in creating tasks")
	}

	if rawWorkflowRun.WorkflowRun.TenantID != tenantId {
		return nil, fmt.Errorf("tenantId mismatch in the triggered workflow run")
	}

	details, err := t.getWorkflowRunDetails(
		ctx.Request().Context(),
		tenantId,
		rawWorkflowRun,
		authz.CanViewPayloads(ctx),
		false,
	)

	if err != nil {
		return nil, err
	}

	if request.Body.AdditionalMetadata != nil {
		correlationIdInterface, ok := (*request.Body.AdditionalMetadata)[string(constants.CorrelationIdKey)]
		if ok {
			correlationId, ok := correlationIdInterface.(string)
			if ok {
				ctx.Set(constants.CorrelationIdKey.String(), correlationId)
			}
		}
	}

	ctx.Set(constants.ResourceIdKey.String(), rawWorkflowRun.WorkflowRun.ExternalID.String())
	ctx.Set(constants.ResourceTypeKey.String(), constants.ResourceTypeWorkflowRun.String())

	// Search for api errors to see how we handle errors in other cases
	return gen.V1WorkflowRunCreate200JSONResponse(
		*details,
	), nil
}

tenant_handler.Text:
package tenants

import (
	"errors"

	"github.com/jackc/pgx/v5"
