cel_evaluation.Text:
func (p *CELParser) ParseAndEvalIdempotencyKey(idempotencyKeyExpr string, in Input) (string, error) {
	prg, err := p.ParseIdempotencyKey(idempotencyKeyExpr)
	if err != nil {
		return "", err
	}

	var inMap map[string]interface{} = in

	out, _, err := prg.Eval(inMap)
	if err != nil {
		return "", err
	}

	// Switch on the type of the output.
	switch out.Type() {
	case types.StringType:
		return out.Value().(string), nil
	default:
		return "", fmt.Errorf("output must evaluate to a string: got %s", out.Type().TypeName())
	}
}

trigger_rpc.Text:
func (a *AdminServiceImpl) TriggerWorkflowRun(ctx context.Context, req *contracts.TriggerWorkflowRunRequest) (*contracts.TriggerWorkflowRunResponse, error) {
	tenant := ctx.Value("tenant").(*sqlcv1.Tenant)
	tenantId := tenant.ID
	a.analytics.Count(ctx, analytics.WorkflowRun, analytics.Create, analytics.Props(
		"has_priority", req.Priority != nil,
		"has_additional_meta", len(req.AdditionalMetadata) > 0,
		"has_desired_worker_labels", len(req.DesiredWorkerLabels) > 0,
	))

	canCreateTR, trLimit, err := a.repo.TenantLimit().CanCreate(
		ctx,
		sqlcv1.LimitResourceTASKRUN,
		tenantId,
		// NOTE: this isn't actually the number of tasks per workflow run, but we're just checking to see
		// if we've exceeded the limit
		1,
	)

	if err != nil {
		return nil, fmt.Errorf("could not check tenant limit: %w", err)
	}

	if !canCreateTR {
		return nil, connect.NewError(connect.CodeResourceExhausted, fmt.Errorf("tenant has reached %d%% of its task runs limit", trLimit))
	}

	opt, err := a.newTriggerOpt(ctx, tenantId, req)

	if err != nil {
		if re, ok := err.(*v1.TriggerOptInvalidArgumentError); ok {
			return nil, connect.NewError(connect.CodeInvalidArgument, fmt.Errorf("Invalid request: %s", re.Err))
		}

		return nil, fmt.Errorf("could not create trigger opt: %w", err)
	}

	err = a.generateExternalIds(ctx, tenantId, []*v1.WorkflowNameTriggerOpts{opt})

	if err != nil {
		return nil, fmt.Errorf("could not generate external ids: %w", err)
	}

	idempotencyKeyCollisions, err := a.ingest(
		ctx,
		tenantId,
		opt,
	)

	if err != nil {
		return nil, err
	}

	for _, collision := range idempotencyKeyCollisions {
		if collision.RequestedExternalId == opt.ExternalId {
			detail, err := connect.NewErrorDetail(
				&contracts.IdempotencyCollisionError{
					ExistingRunExternalId: collision.ExistingExternalId.String(),
				},
			)

			if err != nil {
				return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("failed to build idempotency collision error: %v", err))
			}

			collisionErr := connect.NewError(connect.CodeAlreadyExists, errors.New("idempotency key collision"))
			collisionErr.AddDetail(detail)

			return nil, collisionErr
		}
	}

	return &contracts.TriggerWorkflowRunResponse{
		ExternalId: opt.ExternalId.String(),
	}, nil
}

